INSERT INTO player_matches VALUES(45,8,14025257,30,NULL,'2025-26','2025-10-26','Manchester City','H','PL',90,8.099999999999999645,1,'LDM','pivot-centre',6,'4-2-3-1',38.39999999999999858,56.70000000000000284,47.10000000000000142,70,'0,1,1,0,0,1,7,2,4,0,0,8,6,1,1,5,6,6,3,0,1,1,13,3,0','0110015230065114552011X20',NULL,0.02000000000000000041,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,'Defensive midfield anchor in Villa''s disciplined game plan that stifled City. Screened the back four, won midfield duels and famously blocked a Foden shot with his face. Very few forward incursions - a pure holding/ball-winning shift. Passing kept simple and near-flawless (42/43, 4/4 long balls).','Hottest zone defensive-central ~30%, then middle-central ~23%, middle-left ~16%, defensive-left ~13%. ~60% of activity in the central band - the most central/compact heat of the three matches. / Deepest of the three games: average position avgX ~38 / avgY ~56 (clearly own-half, sitting in front of the defence). Movement compressed and deep: 46% defensive third, 46% middle third, only ~9% attacking third. Length range ~x7-64 - rarely crossed into the final third, reflecting the containment role against City.','SofaScore API /event/14025257/lineups + /average-positions (2026-07-02)','HIGH on minutes/rating/avg coords (API); pos_class is a derived 0.4/0.6-lane x 52-depth banding, NULL when <45min.');
INSERT INTO player_matches VALUES(46,10,14025257,30,NULL,'2025-26','2025-10-26','Manchester City','H','PL',74,6.799999999999999823,1,'RAM','RM/AMR',7,'4-2-3-1',56.29999999999999716,22.39999999999999857,47.10000000000000142,40,'0,0,2,1,3,1,1,0,1,10,0,0,2,2,5,0,0,0,4,7,0,1,0,0,0','002131101X002250004701000',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','Average position right side, but with a lower/deeper bias than a pure winger. Hottest zones: right half-space and right flank across the middle and attacking thirds, plus deeper right-midfield territory when he dropped in. Movement: makes runs from deep to start and join moves, then tucks into the right of the bank of four out of possession (the wide man dropping is what turns the 4-2-3-1 into a 4-4-2/4-4-1-1). Genuine goal threat — a shot deflected off Stones just wide and a blocked header from a corner; a McGinn effort was blocked by Dias. Rated ~7. So a busy two-way right-side heatmap. Confidence moderate.','SofaScore API /event/14025257/lineups + /average-positions (2026-07-02)','HIGH on minutes/rating/avg coords (API); pos_class is a derived 0.4/0.6-lane x 52-depth banding, NULL when <45min.');
INSERT INTO player_matches VALUES(47,13,14025257,30,NULL,'2025-26','2025-10-26','Manchester City','H','PL',90,7.5,1,'CAM','pivot-centre',8,'4-2-3-1',46.29999999999999716,47.70000000000000284,47.10000000000000142,48,'1,1,3,2,0,0,1,0,4,2,1,3,2,2,0,0,5,5,9,0,0,3,0,4,0','113200104213220066X003040',NULL,0.07000000000000000667,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','Average position left half-space/left-inside-forward channel, advanced when Villa had the ball. Hottest zones: left half-space and left flank in the attacking and middle thirds, plus deeper touches on the left as he tracked back. Movement: two-way — carried and combined on the left in transition (Villa''s main out-ball down the left), then dropped to fill the left of a bank of four out of possession so the 4-2-3-1 read as a 4-4-2/4-4-1-1 mid-block. Modest attacking output this game (WhoScored/media rating ~6), so his heatmap is more work-rate/coverage than final-third penetration. Confidence moderate — inferred from tactical reports + role, not a pixel read of the image.','SofaScore API /event/14025257/lineups + /average-positions (2026-07-02)','HIGH on minutes/rating/avg coords (API); pos_class is a derived 0.4/0.6-lane x 52-depth banding, NULL when <45min.');
