INSERT INTO player_matches VALUES(59,14,14025014,7,NULL,'2025-26','2025-11-09','Bournemouth','H','PL',71,8.5,1,'LM','LW/AML',8,'4-4-2',55.39999999999999858,64.40000000000000569,52.29999999999999716,55,'2,4,4,0,0,9,7,2,1,0,5,2,0,1,0,3,3,1,4,0,0,0,1,0,6','24400X8210620103314000107',0.2200000000000000011,0.02999999999999999889,2,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,'Opened the scoring on 28'' with a curled ~20-yard free-kick over the wall; created two big chances, plus defensive contribution (three tackles, five recoveries). Two blocked shots, two key passes, ~67% pass completion from 24 attempts; subbed on 71''. Named Man of the Match. NOTE ON RATING: the 9.0 figure is Sportsdunia''s own player-rating system, not confirmed as the SofaScore number — the SofaScore match page for this fixture did not render for me, so treat 9.0 as an approximate/proxy rating for a clear standout, MOTM display (likely high-8s to ~9 on SofaScore too).','Left attacking third dominant (att|left 31%, att|centre 15%) with left middle third support (mid|left 18%, mid|centre 13%); a distinct right-defensive-third cluster (def|right 13%) from tracking back on the right early on — mixed footprint, but attacking volume clearly LEFT. / Heat centroid ~x54.9/y63.9 (0-100, y high = left) — full-width shift (y4-98, x2-91). MEASURED NOTE: reports labelled him "wide-right/right half-space", but measured attacking volume sits left-of-centre; the right-side work is mostly defensive-third recoveries. Scored a curled free-kick. 55 heat points, 44 touches, 2 key passes, 71 min. Rating corrected to SofaScore official 8.5 (the earlier 9.0 was Sportsdunia''s own scale, flagged as proxy).','SofaScore API /event/14025014/lineups + /average-positions (2026-07-02)','HIGH on minutes/rating/avg coords (API); pos_class is a derived 0.4/0.6-lane x 52-depth banding, NULL when <45min.');
