INSERT INTO player_matches VALUES(75,8,14025129,11,NULL,'2025-26','2025-12-03','Brighton & Hove Albion','A','PL',90,7.299999999999999823,1,'LDM','pivot-left',6,'4-2-3-1',42.70000000000000285,64.5,43.39999999999999858,65,'0,2,2,1,0,1,2,1,1,0,4,14,3,3,0,4,10,6,2,0,3,2,2,2,0','01110111103X2203741021110',0.1700000000000000122,0.0100000000000000002,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','This match: paired Kamara but given freedom to surge forward — hot zones stretch from central midfield into both boxes. Scored the 60'' header (arrived at the back post on Cash''s inswinger, out-jumping De Cuyper) and hit the woodwork; won ~7 duels, ~5 tackles. Movement: the key vertical runner from midfield, physically dominant end-to-end. Confidence: MEDIUM-HIGH (corroborated by goal + duel stats).','SofaScore API /event/14025129/lineups + /average-positions (2026-07-02)','HIGH on minutes/rating/avg coords (API); pos_class is a derived 0.4/0.6-lane x 52-depth banding, NULL when <45min.');
INSERT INTO player_matches VALUES(76,10,14025129,11,NULL,'2025-26','2025-12-03','Brighton & Hove Albion','A','PL',77,6.200000000000000177,1,'CAM','RM/AMR',8,'4-2-3-1',56.10000000000000142,36.0,43.39999999999999858,37,'0,0,0,4,3,2,1,1,2,3,1,0,3,2,0,3,0,0,6,6,0,0,0,0,0','000753223520530500XX00000',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','This match: nominal central 10 but had an uncharacteristically quiet, low-influence game (''anonymous'', ''struggled to get into the game'', rated ~5.5); picked up a needless yellow. Expected heat is central just behind Watkins, but he registered few standout touches, so his footprint was muted/central-to-slightly-deep. When Villa protected the lead he pushed up toward Watkins as the second man in a 4-4-2 press. Confidence: MEDIUM on role, higher that his output/footprint was limited.','SofaScore API /event/14025129/lineups + /average-positions (2026-07-02)','HIGH on minutes/rating/avg coords (API); pos_class is a derived 0.4/0.6-lane x 52-depth banding, NULL when <45min.');
INSERT INTO player_matches VALUES(77,13,14025129,11,NULL,'2025-26','2025-12-03','Brighton & Hove Albion','A','PL',90,7.299999999999999823,1,'LAM','pivot-left',9,'4-2-3-1',47.0,75.29999999999999716,43.39999999999999858,67,'0,5,0,0,0,6,7,1,0,1,9,7,2,3,0,7,7,0,0,0,8,1,3,0,0','0600078101X82308800091300',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','This match: nominal left-attack but roamed heavily and drifted infield/central, consistent with his season pattern (PL tactical piece: he ''drops deep, runs in behind, finds pockets between the lines, pulls out wide''). Hottest zones read as left half-space and centre between Brighton''s lines rather than hugging the touchline. Movement: key creative spark — provided the ''searching pass'' from a central/left pocket for Watkins'' 2nd (45+7''), so his influence peaks arriving into the left half-space to feed the channel behind Brighton''s line. Downside noted: lost possession ~20 times, i.e. lots of high-volume touches in congested central zones. Confidence: MEDIUM.','SofaScore API /event/14025129/lineups + /average-positions (2026-07-02)','HIGH on minutes/rating/avg coords (API); pos_class is a derived 0.4/0.6-lane x 52-depth banding, NULL when <45min.');
