INSERT INTO player_matches VALUES(81,10,14025156,12,NULL,'2025-26','2025-12-06','Arsenal','H','PL',75,6.599999999999999645,1,'RAM','RM/AMR',7,'4-2-3-1',55.10000000000000142,24.0,47.29999999999999716,39,'0,0,0,2,2,0,0,3,2,6,1,0,1,5,7,0,0,2,4,3,0,0,0,1,0','00033004391017X0036400010',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','30 touches, 14/19 passing across 39 tracked points. Avg position X=55, Y=24 — advanced and clearly on the RIGHT (mirror image of Rogers on the left), i.e. he started the right-sided wide-mid role, not central midfield. Hottest zones: right half-space / right channel in the middle-to-attacking third, ahead of and outside Cash''s underlap. Movement: like Rogers he inverted to contest long balls and support the pivot centrally, then formed the right side of Villa''s 4-4-2 defensive block. Provided the killer early pass to spring Watkins. High duels-lost count (3 won / 7 lost) reflects a physically committed, transition-heavy shift screening Arsenal''s left.','SofaScore API /event/14025156/lineups + /average-positions (2026-07-02)','HIGH on minutes/rating/avg coords (API); pos_class is a derived 0.4/0.6-lane x 52-depth banding, NULL when <45min.');
INSERT INTO player_matches VALUES(82,9,14025156,12,NULL,'2025-26','2025-12-06','Arsenal','H','PL',90,6.5,1,'CAM','CAM',8,'4-2-3-1',53.39999999999999858,46.70000000000000284,47.29999999999999716,61,'1,1,2,1,1,0,9,0,6,5,0,3,7,3,4,1,5,3,4,0,2,0,0,3,0','112110X076038341634020030',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','52 touches, 28/35 passing, 61 tracked points. Avg position X=53, Y=47 — dead-central and slightly the most balanced of the trio, sitting between Arsenal''s midfield and defensive lines. Hottest zone: central ''zone 14'' pocket between the lines. Movement: the connector who ''found clever spaces between the lines,'' dropping to receive between Zubimendi and the Arsenal back line and stepping up into the half-spaces the fullbacks vacated. Man-marked by Zubimendi in Arsenal''s press, which is why his touch count is moderate; his job was to occupy and pin the pivot so Kamara/Onana could progress.','SofaScore API /event/14025156/lineups + /average-positions (2026-07-02)','HIGH on minutes/rating/avg coords (API); pos_class is a derived 0.4/0.6-lane x 52-depth banding, NULL when <45min.');
INSERT INTO player_matches VALUES(83,13,14025156,12,NULL,'2025-26','2025-12-06','Arsenal','H','PL',90,6.799999999999999823,1,'LAM','LW/AML',9,'4-2-3-1',56.10000000000000142,62.79999999999999716,47.29999999999999716,75,'8,3,1,2,2,4,7,2,3,6,2,5,2,1,1,6,7,2,0,2,7,1,0,1,0','X413359348363118930391010',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','Team-high 75 tracked touch-points and 56 total touches. SofaScore avg position X=56, Y=63 — advanced and left-of-centre, but NOT hugging the touchline. Hottest zones: left half-space and central left channel in the attacking half, plus a clear cold-defensive smear from tracking back. Movement: heavily inverting — repeatedly tucked inside off the left to ''support the double pivot in building through the centre'' and to contest Martínez''s longer goal-kicks. In the late-game defensive phase (after Arsenal''s subs) he recovered very deep, ''almost acting as a second full-back'' on Villa''s 5-3-2/5-4-1 block. His 29'' left-side cross reached the back post for Cash''s blocked shot. High duel volume (15 won / 11 lost) reflects a busy two-way, transition-heavy game rather than a touchline chalk-hugger.','SofaScore API /event/14025156/lineups + /average-positions (2026-07-02)','HIGH on minutes/rating/avg coords (API); pos_class is a derived 0.4/0.6-lane x 52-depth banding, NULL when <45min.');
