INSERT INTO player_matches VALUES(91,10,14025210,14,NULL,'2025-26','2025-12-14','West Ham United','A','PL',90,7.0,1,'RAM','RM/AMR',7,'4-2-3-1',52.0,24.39999999999999858,59.5,55,'0,1,2,0,2,0,2,1,3,8,0,1,4,2,13,0,1,2,2,7,0,0,0,2,2','01202021260132X0122500022',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','QUALITATIVE READ. Started right of the front line but with typical McGinn box-to-box roaming — hot zones on the right half-space/right channel plus deeper central touches. Assisted the 9th-min own goal with a ''teasing'' cross from the right, and played passes in behind for Rogers and (later) Malen. MOVEMENT: shuttles between the right flank (overlapping/underlapping with Cash) and central areas; also noted pressing at the back post. His side (right) was Villa''s crossing/service side while the left (Rogers/Maatsen) was the primary progression channel targeting the space behind Wan-Bissaka.','SofaScore API /event/14025210/lineups + /average-positions (2026-07-02)','HIGH on minutes/rating/avg coords (API); pos_class is a derived 0.4/0.6-lane x 52-depth banding, NULL when <45min.');
INSERT INTO player_matches VALUES(92,9,14025210,14,NULL,'2025-26','2025-12-14','West Ham United','A','PL',90,7.200000000000000177,1,'CAM','pivot-centre',8,'4-2-3-1',51.60000000000000142,59.0,59.5,78,'3,5,0,0,1,2,8,6,0,3,6,8,8,4,2,3,4,6,4,0,0,1,0,4,0','460013X8048XX534585001050',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','QUALITATIVE READ. Started centrally as the 10 but with wide licence — the assist for the 2-2 came from a ''lung-busting run down the right''/whipped cross after West Ham (Paquetá) gave the ball away, so his heat shows a central base with a strong right-side/right half-space spike into the final third. Described as thriving in the 10 role and Villa''s chief creator. MOVEMENT: central-to-right drift, arriving late into the right channel and the box; box-to-box involvement across both phases. Reconciles the earlier report language (''run down the right'') with him being the nominal central 10.','SofaScore API /event/14025210/lineups + /average-positions (2026-07-02)','HIGH on minutes/rating/avg coords (API); pos_class is a derived 0.4/0.6-lane x 52-depth banding, NULL when <45min.');
