INSERT INTO player_matches VALUES(237,12,14025257,30,NULL,'2025-26','2025-10-26','Manchester City','H','PL',90,6.900000000000000355,1,'RDM','pivot-right',5,'4-2-3-1',41.89999999999999858,33.60000000000000142,47.10000000000000142,83,'0,0,0,1,0,0,3,3,7,4,0,3,1,11,8,2,1,6,17,6,0,0,1,8,1','000100224202165114X400151',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','Average position deep-central, in front of the back four. Hottest zones: central channel in the middle third; frequently drops to the base/between or just ahead of the center-backs. In the mid-block Villa''s shape became a 5-4-1 at times with Kamara dropping into the backline for ''extra solidarity'' (per Total Football Analysis). In build-up he formed passing triangles with the CBs and full-backs and occasionally carried into the wide/right channel. So his heatmap is compact and central with a deep bias, spilling right and toward the back line. Rated ~7. Confidence moderate-high — corroborated by two tactical sources.','SofaScore API /event/14025257/average-positions (2026-07-02)','HIGH on avg coords (API). Minutes/rating not captured in this sweep; pos_class derived from coords alone. Collected to settle the pivot-side question; no appearances after 2026-01-10 (injury).');
