INSERT INTO player_matches VALUES(243,12,14025093,10,NULL,'2025-26','2025-11-30','Wolverhampton','H','PL',88,7.799999999999999823,1,'RDM','RM/AMR',5,'4-2-3-1',53.0,36.0,52.10000000000000142,79,'0,0,2,0,1,0,4,6,15,5,0,0,1,19,4,0,5,8,5,3,0,0,0,1,0','0010102383001X20343200010',0.05999999999999999778,0.02999999999999999889,NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,'Holding midfielder who stepped forward to decide the derby: scored the 67th-minute winner, a ~20-yard strike into the top corner (Sky Sports Man of the Match). More progressive on the ball than usual for a pivot — 50/59 passes (85%), 32/37 in the opposition half, 71 touches. Defensive contribution lighter than his best games (2 tackles, 1 recovery, duels split 7 won/8 lost).','Hottest zones: left-of-center midfield (33%) and central midfield (27%), with pockets in the attacking third (center 9%, left 9%). Split ~48% left / 43% center / 9% right; ~16% defensive / 66% middle / 18% attacking third. / Average position advanced to roughly the halfway line (SofaScore coords ~x52/y36), reflecting a more forward, box-arriving role. Ranged from own third up to the Wolves box (x-max 94); ~66% of his activity was in the middle third with pushes into the left half-space where his shot originated.','SofaScore API /event/14025093/average-positions (2026-07-02)','HIGH on avg coords (API). Minutes/rating not captured in this sweep; pos_class derived from coords alone. Collected to settle the pivot-side question; no appearances after 2026-01-10 (injury).');
INSERT INTO player_matches VALUES(244,12,14025129,11,NULL,'2025-26','2025-12-03','Brighton & Hove Albion','A','PL',70,6.400000000000000355,1,'RDM','pivot-centre',5,'4-2-3-1',48.0,43.29999999999999715,43.39999999999999858,34,'0,0,0,0,0,0,2,3,4,2,0,3,6,3,1,0,0,3,3,1,0,0,1,1,1','000000357305X520055200222',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','This match: lowest and most central of the midfield, hottest zone just ahead of the back four in central/left-central areas. Sat as the anchor (''a solid shield in front of the back four'') while Onana advanced — effectively the lone screen when both FBs pushed on. Movement: minimal vertical roaming; tidy, possession-recycling role, kept the ball moving before being subbed. Confidence: MEDIUM.','SofaScore API /event/14025129/average-positions (2026-07-02)','HIGH on avg coords (API). Minutes/rating not captured in this sweep; pos_class derived from coords alone. Collected to settle the pivot-side question; no appearances after 2026-01-10 (injury).');
INSERT INTO player_matches VALUES(245,12,14025156,12,NULL,'2025-26','2025-12-06','Arsenal','H','PL',90,7.599999999999999645,1,'RDM','pivot-right',5,'4-2-3-1',50.5,36.29999999999999715,47.29999999999999716,76,'0,2,4,1,4,0,0,3,4,9,1,4,4,9,5,1,6,4,4,3,0,0,2,2,4','024140034X144X61744300224',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','Team-high 76 tracked points and 60 touches with excellent 42/46 passing. Avg position X=50, Y=36 — the true anchor: deepest of the outfield midfielders, sat slightly right of centre in front of the back line (roughly ahead of Konsa). Hottest zone: central-to-right defensive third and halfway line. Movement: the low-mobility screen — held position to shield the space Zubimendi/Ødegaard/Rice attacked, tidied second balls, and recycled possession to beat the press. 4 tackles won + 1 interception; the least vertical of Villa''s midfield trio, providing the base that let Tielemans push up and the fullbacks fly forward.','SofaScore API /event/14025156/average-positions (2026-07-02)','HIGH on avg coords (API). Minutes/rating not captured in this sweep; pos_class derived from coords alone. Collected to settle the pivot-side question; no appearances after 2026-01-10 (injury).');
