INSERT INTO player_matches VALUES(548,2,14025156,12,NULL,'2025-26','2025-12-06','Arsenal','H','PL',87,7.799999999999999823,1,'RB','RM/AMR',1,'4-2-3-1',52.10000000000000142,17.80000000000000071,47.29999999999999716,59,'2,0,0,4,5,0,0,0,2,10,0,0,0,0,15,0,0,0,3,10,0,0,2,4,2','10033000170000X0002700131',0.25,0.05000000000000000277,1,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,'Starting right-back in a 4-2-3-1; balanced two-way full-back display against Arsenal — high up the right when Villa attacked but with more defensive recovery work than the Sunderland game. Substituted around the 87th minute.','Right flank across all three zones, tilted to right middle third (41%) with roughly equal defensive (29%) and attacking (31%) presence / Balanced heatmap: average position around the halfway line on the right, avg coords approx (x=52, y=17). Movement split a fairly even 29% defensive third / 41% middle third / 31% attacking third — genuinely two-way. 81% of touches on the right touchline (y<25). Lower touch count (51-59 touches) reflecting a more end-to-end, transitional game and his early-ish substitution; 28/32 passing, 1 tackle, 4 clearances, 1 interception, 1 key pass, 3 duels won. Got on the scoresheet in the 2-1 win.','SofaScore API /event/14025156/lineups players[] 배열순서 + /average-positions (2026-07-31)','HIGH on minutes/rating/avg coords (API). lineup_order는 라인업 배열 인덱스 = 원천값이고 좌표 역산이 아니다. lineup_pos는 (formation, order) 파생 — 실측 y 레인과 대조 검증됨. pos_class는 minutes<45일 때 NULL(좌표 평균 신뢰불가).');
INSERT INTO player_matches VALUES(549,16,14025156,12,NULL,'2025-26','2025-12-06','Arsenal','H','PL',66,6.799999999999999823,1,'ST','LW/AML',10,'4-2-3-1',55.20000000000000284,61.39999999999999858,47.29999999999999716,35,'0,2,3,3,0,0,3,3,2,0,3,2,3,0,0,2,4,2,1,0,1,1,0,0,0','0588008850858005X53033000',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','Only 31 touches / 6-of-13 passing — a low-volume, high-threat night typical of leading a compact counter-attacking side vs a possession team. Avg position X=55, Y=61 — modest X for a striker (confirms he repeatedly dropped) and a slight drift to the left channel. Hottest zones: centrally around Arsenal''s defensive line, with a secondary pocket dropping toward the ball. Movement: the described dual role — ''dropped to engage on first contact but also on the shoulder, ready for flick-ons'' off Martínez''s long distribution, giving Villa a two-stage aerial/transition outlet. Best chance early: released by McGinn, beat Timber and White before Raya''s fine save; also tested Raya with a low shot later. 4 duels won / 4 lost.','SofaScore API /event/14025156/lineups players[] 배열순서 + /average-positions (2026-07-31)','HIGH on minutes/rating/avg coords (API). lineup_order는 라인업 배열 인덱스 = 원천값이고 좌표 역산이 아니다. lineup_pos는 (formation, order) 파생 — 실측 y 레인과 대조 검증됨. pos_class는 minutes<45일 때 NULL(좌표 평균 신뢰불가).');
INSERT INTO player_matches VALUES(550,2,14025172,31,NULL,'2025-26','2025-09-21','Sunderland','A','PL',90,7.900000000000000355,1,'RB','RM/AMR',1,'4-2-3-1',54.60000000000000142,14.19999999999999929,71.5,94,'0,0,0,1,10,0,0,1,7,25,0,0,0,4,18,0,0,2,7,13,0,0,1,2,3','000040003X000270013500011',0.05000000000000000277,0.05000000000000000277,NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,'Starting right-back in a 4-2-3-1; his most attacking display of the three — pushed high and wide as Villa''s main source of right-sided width away from home, spending far more time in the opposition half than deep defending. Full 90, not captain.','Right middle third (46%) and right attacking third (32%) — camped high on the flank / Most advanced heatmap of his top matches: average position around midfield/opposition-half on the right, avg coords approx (x=54, y=14). Movement split only 18% defensive third / 46% middle third / 36% attacking third — heavily upfield. 80% of touches on the right touchline (y<25) and NONE on the far side; the y-range capped at ~47, meaning he stayed strictly on the right half of the pitch. 86 touches, 56/62 passing (high volume, high accuracy), 2 tackles, 2 clearances, 1 interception, 5 duels won. Scored Villa''s goal.','SofaScore API /event/14025172/lineups players[] 배열순서 + /average-positions (2026-07-31)','HIGH on minutes/rating/avg coords (API). lineup_order는 라인업 배열 인덱스 = 원천값이고 좌표 역산이 아니다. lineup_pos는 (formation, order) 파생 — 실측 y 레인과 대조 검증됨. pos_class는 minutes<45일 때 NULL(좌표 평균 신뢰불가).');
