INSERT INTO player_matches VALUES(568,2,14025257,30,NULL,'2025-26','2025-10-26','Manchester City','H','PL',90,8.400000000000000355,1,'RB','pivot-right',1,'4-2-3-1',39.5,15.0,47.10000000000000142,85,'2,0,1,0,1,0,0,1,1,15,0,0,0,3,15,0,0,0,2,20,0,0,1,8,15','1010100118000280001X00148',0.05999999999999999778,0.07000000000000000667,1,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,'Starting right-back in a 4-2-3-1; disciplined, defensively-anchored full-back tasked with containing City''s left-side overloads, staying compact rather than over-committing forward, but joining a set-piece routine to score. Not captain, played full 90.','Right defensive-to-middle third channel (mid|right-flank 42%, def|right-flank 38% of activity) / Average position deep-ish on the right, avg pitch coords approx (x=39, y=15) on SofaScore''s 0-100 scale — defensive-leaning for a full-back. Movement split 40% defensive third / 42% middle third / 18% attacking third; 85% of touches hugged the right touchline (y<25). Touch spread reached x=1 to x=99, i.e. he did get all the way forward once (the 19th-minute goal off Buendia''s short-corner routine, curling a low left-footed shot into the bottom corner) but his baseline was a contained, recovery-focused right-back display. 76 touches, 39/48 passing, 2 tackles, 4 clearances, 1 interception, 1 key pass, 1 big chance created, 4 duels won. Named Player of the Match.','SofaScore API /event/14025257/lineups players[] 배열순서 + /average-positions (2026-07-31)','HIGH on minutes/rating/avg coords (API). lineup_order는 라인업 배열 인덱스 = 원천값이고 좌표 역산이 아니다. lineup_pos는 (formation, order) 파생 — 실측 y 레인과 대조 검증됨. pos_class는 minutes<45일 때 NULL(좌표 평균 신뢰불가).');
INSERT INTO player_matches VALUES(569,16,14025257,30,NULL,'2025-26','2025-10-26','Manchester City','H','PL',86,6.299999999999999823,1,'ST','CAM',10,'4-2-3-1',68.90000000000000569,57.29999999999999716,47.10000000000000142,38,'1,4,5,5,0,3,1,1,1,1,4,3,1,2,2,1,0,2,1,0,0,0,0,0,0','28XX062222862442042000000',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'(match heatmap analysis)','Average position high and central, the most advanced Villa player. Hottest zones: central channel in the attacking third and around the edge/inside of the City box; runs onto the shoulder of the last defender. Movement: repeated in-behind runs on defenders'' blindsides to exploit City''s high line in transition — Villa''s chief counter threat; came ''inches away'' from a through-ball and had a header blocked. Lower defensive footprint (front of a mid-block, minimal tracking). Heatmap = a high, narrow central hot spot with vertical run trails toward goal. Confidence moderate.','SofaScore API /event/14025257/lineups players[] 배열순서 + /average-positions (2026-07-31)','HIGH on minutes/rating/avg coords (API). lineup_order는 라인업 배열 인덱스 = 원천값이고 좌표 역산이 아니다. lineup_pos는 (formation, order) 파생 — 실측 y 레인과 대조 검증됨. pos_class는 minutes<45일 때 NULL(좌표 평균 신뢰불가).');
